      "content": "High-Yield Panic Pack Question: Basic Electrical Engineering (ES-EE101)\nTopic: Th\u00e9venin's Theorem | Exam Marks: 10 Marks | Repetition Frequency: Seen 5 Times (2019, 2021, 2022, 2023, 2024)\nExam Question: State and prove Th\u00e9venin's Theorem. Calculate load current through 10 ohm load using Th\u00e9venin equivalent in dual-source bridge.\nVerified Model Solution: 1. Remove RL. 2. Calculate Voc (Vth) across terminals AB using nodal equations. 3. Deactivate all independent sources to calculate Rth. 4. Equivalent load current: IL = Vth / (Rth + RL).",
