      "title": "Panic Pack: Maxwell's Equations (BS-PH101)",
      "content": "High-Yield Panic Pack Question: Physics (BS-PH101)\nTopic: Maxwell's Equations | Exam Marks: 10 Marks | Repetition Frequency: Seen 5 Times (2018, 2019, 2022, 2024)\nExam Question: Write down Maxwell's four equations in differential and integral forms. Explain physical significance of displacement current.\nVerified Model Solution: 1. div D = rho (Gauss's law). 2. div B = 0 (No magnetic monopoles). 3. curl E = -dB/dt (Faraday's law). 4. curl H = J + dD/dt (Ampere-Maxwell law with displacement current dD/dt).",
