      "title": "Panic Pack: Nernst Equation & Cell EMF (BS-CH101)",
      "content": "High-Yield Panic Pack Question: Chemistry (BS-CH101)\nTopic: Nernst Equation & Cell EMF | Exam Marks: 10 Marks | Repetition Frequency: Seen 5 Times (2019, 2021, 2022, 2023, 2024)\nExam Question: Derive Nernst equation for single electrode potential and cell EMF. Calculate EMF of Zn | Zn2+(0.01M) || Cu2+(0.1M) | Cu at 298 K (E\u00b0_cell = 1.10 V).\nVerified Model Solution: Delta G = Delta G\u00b0 + RT ln Q. Since Delta G = -nFE, E = E\u00b0 - (2.303 RT / nF) log Q. At 298 K: E = 1.10 - (0.0591 / 2) log(0.01 / 0.1) = 1.1295 V.",
