      "title": "Panic Pack: EDTA Hardness Determination (BS-CH101)",
      "content": "High-Yield Panic Pack Question: Chemistry (BS-CH101)\nTopic: EDTA Hardness Determination | Exam Marks: 5 Marks | Repetition Frequency: Seen 4 Times (2019, 2020, 2022, 2023)\nExam Question: Explain the principle of determination of water hardness using EDTA titration method with EBT indicator.\nVerified Model Solution: Disodium salt of EDTA forms stable, colorless soluble chelate complexes with Ca2+ and Mg2+ ions at pH 10 (buffered with NH4Cl-NH4OH). Eriochrome Black T (EBT) forms a wine-red complex which turns pure blue at endpoint.",
