      "title": "Panic Pack: Cayley-Hamilton Theorem (BS-M101)",
      "content": "High-Yield Panic Pack Question: Mathematics - I (BS-M101)\nTopic: Cayley-Hamilton Theorem | Exam Marks: 10 Marks | Repetition Frequency: Seen 5 Times (2018, 2019, 2021, 2022, 2023)\nExam Question: State Cayley-Hamilton Theorem. Verify it for matrix A = [[1, 2], [3, 4]] and compute A^-1.\nVerified Model Solution: Every square matrix satisfies its characteristic polynomial det(A - lambda*I) = 0. Polynomial: lambda^2 - 5*lambda - 2 = 0. Verify A^2 - 5A - 2I = 0. Multiply by A^-1: A^-1 = (A - 5I)/2.",
