      "title": "Panic Pack: Convolution Theorem in Laplace (BS-M201)",
      "content": "High-Yield Panic Pack Question: Mathematics - II (BS-M201)\nTopic: Convolution Theorem in Laplace | Exam Marks: 10 Marks | Repetition Frequency: Seen 4 Times (2019, 2021, 2023, 2024)\nExam Question: State and prove Convolution Theorem for Laplace transform. Evaluate L^-1{ 1 / [s*(s^2 + 1)] }.\nVerified Model Solution: L^-1{ F(s)*G(s) } = integral from 0 to t of f(u)*g(t-u) du. Let F(s)=1/s (f(t)=1) and G(s)=1/(s^2+1) (g(t)=sin t). Integral 0 to t of sin(u) du = 1 - cos(t).",
      "source_file": "docs/app.js",
