      "content": "High-Yield Panic Pack Question: Data Structure & Algorithms (PCC-CS301)\nTopic: Quicksort Partition & Complexity | Exam Marks: 10 Marks | Repetition Frequency: Seen 5 Times (2019, 2021, 2022, 2023, 2024)\nExam Question: Explain Lomuto and Hoare partitioning schemes in Quicksort. Derive average and worst-case time complexity.\nVerified Model Solution: Quicksort selects a pivot, partitions array such that elements < pivot are to left and > pivot to right. Best/Average case: O(n log n). Worst case: O(n^2) when array is already sorted and pivot is extreme element.",
