      "content": "High-Yield Panic Pack Question: Database Management Systems (PCC-CS601)\nTopic: 3NF vs BCNF Decomposition | Exam Marks: 10 Marks | Repetition Frequency: Seen 5 Times (2019, 2021, 2022, 2023, 2024)\nExam Question: Define Third Normal Form (3NF) and Boyce-Codd Normal Form (BCNF). Why is BCNF strictly stronger than 3NF?\nVerified Model Solution: A relation R is in 3NF if for every FD X -> A, either X is a superkey or A is a prime attribute. R is in BCNF if for every non-trivial FD X -> A, X is a superkey. BCNF eliminates all redundancy due to FDs but may not always preserve dependencies.",
